+function getSuggestedReason(owner: IssueOwner) {
+  if (owner.commits) {
+    return t('Suspect commit author');
+  }
+
+  if (owner.rules?.length) {
+    const firstRule = owner.rules[0];
+    return t('Owner of %s', firstRule.join(':'));
+  }
+
